# Generated by Selenium IDE
import pytest
import time
import json
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.common.action_chains import ActionChains
from selenium.webdriver.support import expected_conditions
from selenium.webdriver.support.wait import WebDriverWait
from selenium.webdriver.common.keys import Keys
from selenium.webdriver.common.desired_capabilities import DesiredCapabilities

class TestChatbott():
  def setup_method(self, method):
    self.driver = webdriver.Chrome()
    self.vars = {}
  
  def teardown_method(self, method):
    self.driver.quit()
  
  def test_chatbott(self):
    self.driver.get("http://localhost:5173/login")
    self.driver.maximize_window()
    
    # 1. Wait for email input and enter Student credentials
    email_input = WebDriverWait(self.driver, 10).until(
        expected_conditions.presence_of_element_located((By.NAME, "email"))
    )
    email_input.clear()
    email_input.send_keys("student1@example.com")
    
    password_input = self.driver.find_element(By.NAME, "password")
    password_input.clear()
    password_input.send_keys("123456")
    
    submit_btn = self.driver.find_element(By.XPATH, "//button[@type='submit']")
    submit_btn.click()
    
    # 2. Wait for redirect to student dashboard
    WebDriverWait(self.driver, 10).until(
        expected_conditions.url_contains("/student/dashboard")
    )
    
    # 3. Wait for chatbot floating button to be clickable and click it
    bot_btn = WebDriverWait(self.driver, 10).until(
        expected_conditions.element_to_be_clickable((By.CSS_SELECTOR, "button.fixed.bottom-6.right-6"))
    )
    bot_btn.click()
    
    # 4. Wait for chat input field
    chat_input = WebDriverWait(self.driver, 10).until(
        expected_conditions.visibility_of_element_located((By.CSS_SELECTOR, "form input[type='text']"))
    )
    chat_input.click()
    chat_input.send_keys("What is atomicity in chemistry?")
    chat_input.send_keys(Keys.ENTER)
    
    # 5. Wait for message to appear in chat
    time.sleep(3)
    
    # Assert chat opened and message was submitted
    assert "/student/dashboard" in self.driver.current_url
    print("\n✅ CHATBOT TEST PASSED! Student logged in, asked query to AI assistant successfully.")

if __name__ == "__main__":
    pytest.main(["test_chatbott.py", "-v", "-s"])
